let sql = ($json.text || $json.response || '').toString();
// Bo markdown fences neu LLM lo them
sql = sql.replace(/```sql/gi, '').replace(/```/g, '').trim();
// Lay tu chu SELECT dau tien
const up = sql.toUpperCase();
const idx = up.indexOf('SELECT');
if (idx >= 0) sql = sql.slice(idx);
// Bo dau ; va khoang trang thua o cuoi
sql = sql.replace(/;\s*$/, '').trim();
// Chan tuyet doi: chi cho phep SELECT
if (!/^SELECT/i.test(sql)) {
  sql = "SELECT 'KHONG_HOP_LE' AS thong_bao";
}
if (/\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REPLACE)\b/i.test(sql)) {
  sql = "SELECT 'KHONG_HOP_LE' AS thong_bao";
}
return [{ json: { sql } }];

// Gom tat ca dong ket qua thanh 1 item de node tra loi chay 1 lan
const all = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
let question = '';
try { question = $('Webhook').first().json.body.noi_dung_tin_nhan || ''; } catch (e) {}
return [{ json: { question, row_count: all.length, rows_json: JSON.stringify(all) } }];

let raw = ($json.text || '').toString().replace(/```json/gi, '').replace(/```/g, '').trim();
let out = { response: 'SunLens AI chưa có phản hồi.', need_staff: false, loai_yeu_cau: 'KHAC', tom_tat: '' };
try {
  const m = raw.match(/\{[\s\S]*\}/);
  const obj = JSON.parse(m ? m[0] : raw);
  out.response = (obj.tra_loi || obj.response || '').toString().trim() || out.response;
  out.need_staff = obj.can_nhan_vien === true || obj.can_nhan_vien === 'true';
  const cat = (obj.loai_yeu_cau || 'KHAC').toString().toUpperCase();
  out.loai_yeu_cau = ['KHIEU_NAI','HUY_DON','HOAN_TIEN','CAN_XAC_NHAN','KHAC'].includes(cat) ? cat : 'KHAC';
  out.tom_tat = (obj.tom_tat || '').toString().trim();
} catch (e) {
  out.response = raw || out.response;
}
if (!out.need_staff) { out.loai_yeu_cau = 'KHAC'; out.tom_tat = ''; }
return [{ json: out }];
